#' Quantile estimation
#' 
#' This function estimates quantiles of plausible values within groups.
#' 
#' 
#' @param by A formula statement is expected which splits the data into several
#' subsets. Within these subsets the quantiles are estimated.
#' @param svydat A survey design (\code{svydesign} as well as
#' \code{svrepdesign}) which was generated by the \code{survey} package. To
#' figure out how to create a survey design object, please read the help files
#' for the \code{survey} package.
#' @param pvs A character vector which includes the colnames of the plausible
#' values. These variables must be part of the survey design comitted as
#' \code{svydat}.
#' @param quantile A numeric vector of length > 1 which contains the quantiles
#' of interest.
#' @param interval.type A character vector of length = 1 which denotes the kind
#' of quantile estimation method. Valid inputs are: "quantile" and
#' "probability" if a svrepdesign was submitted and in case of a oridinary
#' survey design the valid inputs are: "Wald", "score" and "betaWald". More
#' information about the different estimation techniques can be gained from the
#' "Details" section of the \code{svyquantile} function in the \code{survey}
#' package.
#' @param \dots More arguments which are forwarded to \code{svyquantile}.
#' @param colN If TRUE the colnames will equal the grouping variable names from
#' the by statement. If FALSE, which is the default, the names will be Group1
#' up to Group k.
#' @return The function returns a data.frame with the following columns
#' \item{Group1..k}{The first k columns show the different levels of the k
#' subsetting groups.} \item{Number.of.cases}{Shows the unweighted number of
#' cases (NA's excluded) within each group.} \item{Sum.of.weights}{Shows the
#' sum of weights (NA's excluded) within each group.} \item{q0...}{These
#' columns contain the quantile values which were estimated by means of the
#' submitted plausible values.}
#' @author Manuel Reif
#' @seealso \code{\link{svyPVpm}}
#' @references Lumley, T. (2010). \emph{Complex Surveys}. Hoboken, NJ: Wiley.
#' 
#' Saerndal, C.-E. & Swensson, B. & Wretman, J. (1992). \emph{Model Assisted
#' Survey Sampling}. New York: Springer.
#' 
#' Chaudhuri, A. & Stenger, H. (2005). \emph{Survey Sampling. Theory and
#' Methods}. Boka Raton, FL: Chapman & Hall/CRC.
#' @keywords quantile
#' @examples
#' 
#' data(svy_example1)
#' 
#' erg_q <- svyPVquantile(by = ~ sex, svydat=svy.exrep,
#' pvs=c("plaus1","plaus2","plaus3"), quantile=c(0.2,0.7))
#' 
#' erg_q
#' 
#' @export svyPVquantile
svyPVquantile <-
function(by, svydat, pvs, quantile, interval.type="quantile", colN=FALSE, ...)
{

ergquant <- pv_quantile(by=by, svydat=svydat, pvs=pvs, quantile=quantile,  interval.type=interval.type, ...)
pm       <- mergeALL(ergquant)  



### um die ordnung der factors gleich zu lassen (vor allem wichtig bezogen auf grafiken) wird hier nochmal umgeordnet so wie es im datensatz ?blich ist

mybys <- all.vars(by)
# facordall <- mapply(function(x,number) factor(pm[,number], levels=levels(svydat$variables[[x]])), x=mybys, number=1:length(mybys),SIMPLIFY=FALSE)
# 
# facordallDF <- data.frame(facordall)

facordallDF <- fALL(mybys,pm, svydat)

pm[,1:length(mybys)] <- facordallDF


if(colN)
{
  colnames(pm)[1:length(mybys)] <- c(mybys) 
  
}




# if(addcountry)
# {  
#   pm  <- data.frame("Country"=unique(svydat$variables$CNTRYID), pm) 
# }

pm  
}
